#' }
#'
#' @export
CHMChiSquareTest <- function(
    data,
    rc,
    h,
    correct = TRUE,
    a = "0.05") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("CHMChiSquareTest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(rc)) rc <- jmvcore::resolveQuo(jmvcore::enquo(rc))
    if ( ! missing(h)) h <- jmvcore::resolveQuo(jmvcore::enquo(h))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(rc), rc, NULL),
            `if`( ! missing(h), h, NULL))


    options <- CHMChiSquareTestOptions$new(
        rc = rc,
        h = h,
        correct = correct,
        a = a)

    analysis <- CHMChiSquareTestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

